@if($errors->any())<div class="alert alert-danger" role="alert">Please correct the highlighted fields.</div>@endif
<div class="card admin-card"><div class="card-body p-4"><div class="row"><div class="col-lg-6"><x-admin.form-input name="name" label="Role name" :value="$managedRole?->name" required help="Lowercase letters, numbers and underscores only." :readonly="$managedRole?->name === 'super_admin'" /></div></div><fieldset class="mt-3"><div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-3"><legend class="h5 mb-0">Permissions</legend><div class="d-flex gap-2"><button class="btn btn-sm btn-outline-success" type="button" data-check-permissions>Check all</button><button class="btn btn-sm btn-outline-secondary" type="button" data-uncheck-permissions>Clear all</button></div></div>@php($selectedPermissions=old('permissions', $managedRole?->permissions->pluck('name')->all() ?? []))<div class="row g-4">@foreach($permissionGroups as $group=>$permissions)<div class="col-md-6 col-xl-4"><section class="permission-group h-100"><div class="d-flex justify-content-between align-items-center"><h3 class="h6 mb-0">{{ $group }}</h3><button class="btn btn-link btn-sm p-0" type="button" data-check-group>Select group</button></div><div class="mt-3">@foreach($permissions as $permission)<label class="form-check mb-2"><input class="form-check-input" type="checkbox" name="permissions[]" value="{{ $permission->name }}" @checked(in_array($permission->name, $selectedPermissions, true))><span class="form-check-label">{{ str($permission->name)->after('.')->replace('_', ' ')->replace('.', ' ')->title() }}</span><small class="d-block text-muted">{{ $permission->name }}</small></label>@endforeach</div></section></div>@endforeach</div></fieldset></div></div>
@push('scripts')<script>document.querySelector('[data-check-permissions]')?.addEventListener('click',()=>document.querySelectorAll('input[name="permissions[]"]').forEach(input=>input.checked=true));document.querySelector('[data-uncheck-permissions]')?.addEventListener('click',()=>document.querySelectorAll('input[name="permissions[]"]').forEach(input=>input.checked=false));document.querySelectorAll('[data-check-group]').forEach(button=>button.addEventListener('click',()=>button.closest('.permission-group').querySelectorAll('input[type="checkbox"]').forEach(input=>input.checked=true)));</script>@endpush
